// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, address caller, uint256 claimAmount) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(claimAmount > 0 && claimAmount <= type(uint128).max);

        // Ensure we have some shares to claim by making a deposit
        address receiver = address(0x123);
        vm.deal(address(this), 1 ether);
        // We need to call depositUsdc to create a deposit record; but we need to set up the vault mock etc.
        // Since we cannot, we simply check the owner after calling transferOwnership then claim.

        // Transfer ownership to newOwner
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Now call claim (but claim will likely revert because no shares, so we wrap in try/catch)
        bool claimed;
        try c.claim(caller, claimAmount) {
            claimed = true;
        } catch {
            claimed = false;
        }

        // After the call, the owner should still be newOwner (because the bug in transferOwnership always sets to address(0))
        // But since we assume newOwner != address(0), the reference would have owner == newOwner, while mutant would have owner == address(0)
        // So we assert that owner == newOwner, which holds for reference but fails for mutant
        assertTrue(c.owner() == newOwner);
    }
}

